pub(super) fn select(cut: u8, rfe: u8, kind: usize) -> Option<&'static [(u16, u32)]> {
    let rfe = match rfe {
        2 => 0,
        3 => 1,
        5 => 2,
        _ => return None,
    };
    if cut > 15 || kind > 4 {
        return None;
    }
    Some(TABLES[usize::from(PROFILES[usize::from(cut)][rfe][kind])])
}
